<script>
(function(){const cat=document.getElementById('main_category'),sub=document.getElementById('subcategory'),unit=document.getElementById('unit'),supplierLabel=document.getElementById('supplier_label'),recommendations=@json($lookups['unitRecommendations']);function filter(){Array.from(sub.options).forEach(o=>{if(!o.value)return;o.hidden=o.dataset.parent!==cat.value;if(o.hidden&&o.selected)sub.value='';});}function guide(){const preferred=recommendations[cat.value]||[];Array.from(unit.options).filter(o=>o.value).sort((a,b)=>(preferred.indexOf(a.value)<0?1000:preferred.indexOf(a.value))-(preferred.indexOf(b.value)<0?1000:preferred.indexOf(b.value))).forEach(o=>unit.appendChild(o));supplierLabel.textContent=cat.value==='labour_subcontracts'?'Expected Fundi / Contractor / Service Provider':cat.value==='materials'?'Expected Supplier':'Expected Supplier / Service Provider';}cat.addEventListener('change',filter);cat.addEventListener('change',guide);filter();guide();function cents(v){const p=String(v||'0').split('.');return BigInt(p[0]||'0')*100n+BigInt((p[1]||'').padEnd(2,'0').slice(0,2)||'0');}function preview(){const q=cents(document.getElementById('quantity').value||'1'),u=cents(document.getElementById('unit_cost').value),t=(q*u+50n)/100n;document.getElementById('line_total').value=(t/100n).toLocaleString()+'.'+String(t%100n).padStart(2,'0');}['quantity','unit_cost'].forEach(id=>document.getElementById(id).addEventListener('input',preview));preview();})();
</script>
